class _ProxyMeterConfig:
    """Proxy wrapper around a ``_MeterConfig`` that supports in-place updates.

    Instruments hold a reference to the same ``_ProxyMeterConfig`` as their
    Meter, so updating the underlying config immediately affects all of the
    Meter's instruments.
    """

    def __init__(self, config: _MeterConfig):
        self._config = config

    @property
